#!/bin/sh
# Rescore the test_reid.py outputs with the strict criterion (rms < 0.5
# px, >= 30 lines, max |dlambda| < 2 A), per file and detector.
# Generated by JXP and Claude (dev script, not part of PypeIt).
cd "$(dirname "$0")"
for f in reid_self.txt reid_loo.txt reid_xdet.txt reid_xdet_nreid*.txt \
         reid_*_mt*.txt; do
  [ -f "$f" ] || continue
  awk -v f="$f" '
    /^  [12] / { n[$1]++
      if ($6 != "no" && $6 < 0.5 && $7 >= 30 && $9 < 2) g[$1]++
      else bad[$1] = bad[$1] " " $2 }
    END { printf "%-26s DET01 %2d/%2d  DET02 %2d/%2d  failed:%s |%s\n",
          f, g[1], n[1], g[2], n[2], bad[1], bad[2] }' "$f"
done
